/** Small SQL identifier helpers shared by the executor and the dataset importer. */

const SAFE_IDENT = /^[a-z_][a-z0-9_]{0,62}$/;

/** Quote an identifier for interpolation into SQL. */
export function quoteIdent(name: string): string {
  return `"${name.replace(/"/g, '""')}"`;
}

/** Schema / role names generated by this application (ds_<hex>, nl2sql_ro_<hex>, shop, nl2sql_readonly). Refuses anything else. */
export function assertSafeIdent(name: string, what = "identifier"): string {
  if (!SAFE_IDENT.test(name)) throw new Error(`Refusing to use unsafe ${what}: ${name.slice(0, 40)}`);
  return name;
}

const RESERVED = new Set([
  "all", "analyse", "analyze", "and", "any", "array", "as", "asc", "both", "case", "cast", "check", "collate", "column", "constraint", "create",
  "current_date", "current_time", "current_timestamp", "current_user", "default", "desc", "distinct", "do", "else", "end", "except", "false",
  "fetch", "for", "foreign", "from", "grant", "group", "having", "in", "initially", "intersect", "into", "leading", "limit", "not", "null", "offset",
  "on", "only", "or", "order", "placing", "primary", "references", "returning", "select", "session_user", "some", "symmetric", "table", "then", "to",
  "trailing", "true", "union", "unique", "user", "using", "variadic", "when", "where", "window", "with",
]);

/** Name as it must be written in SQL: double-quoted when it is not a plain lower-case identifier or is a reserved word. */
export function sqlName(name: string): string {
  return /^[a-z_][a-z0-9_]*$/.test(name) && !RESERVED.has(name) ? name : quoteIdent(name);
}
